package com.hms.services;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="hospital_services") public class HospitalService { @Id private UUID id; @Column(nullable=false) private UUID tenantId; private UUID departmentId; @Column(nullable=false,length=40) private String code; @Column(nullable=false,length=180) private String name; @Column(length=500) private String description; @Column(precision=12,scale=2) private BigDecimal consultationFee; @Column(nullable=false) private boolean active; @Column(nullable=false) private boolean publicVisible; @Column(nullable=false) private OffsetDateTime createdAt; @Column(nullable=false) private OffsetDateTime updatedAt; protected HospitalService(){} public HospitalService(UUID tenantId,CreateServiceRequest r){this.id=UUID.randomUUID();this.tenantId=tenantId;this.departmentId=r.departmentId();this.code=r.code().trim().toUpperCase();this.name=r.name().trim();this.description=r.description();this.consultationFee=r.consultationFee();this.active=true;this.publicVisible=r.publicVisible();this.createdAt=OffsetDateTime.now();this.updatedAt=createdAt;} public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public UUID getDepartmentId(){return departmentId;} public String getCode(){return code;} public String getName(){return name;} public String getDescription(){return description;} public BigDecimal getConsultationFee(){return consultationFee;} public boolean isActive(){return active;} public boolean isPublicVisible(){return publicVisible;} }
